const urls = [
  'https://federation.ccdi.cancer.gov/api/v1/sample?diagnosis=Lymphoblastic%20Leukemia&library_strategy=RNA-Seq&page=1&per_page=10',
  'https://federation.ccdi.cancer.gov/api/v1/sample?diagnosis=Myeloid%20Leukemia&library_strategy=RNA-Seq&page=1&per_page=10'
];
const results = [];
for (const url of urls) {
  try {
    const res = await fetch(url, { headers: { accept: 'application/json' } });
    const text = await res.text();
    let payload;
    try { payload = JSON.parse(text); } catch { payload = text.slice(0, 1000); }
    results.push({ url, status: res.status, ok: res.ok, headers: { link: res.headers.get('link'), contentType: res.headers.get('content-type') }, payload });
  } catch (e) {
    results.push({ url, ok: false, error: String(e && e.stack || e) });
  }
}
nodeRepl.write(JSON.stringify(results, null, 2).slice(0, 60000));

